25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * AXI4-Stream ethernet frame transmitter (Ethernet frame in, AXI out)
33	 */
34	module eth_axis_tx #
35	(
36	    // Width of AXI stream interfaces in bits
37	    parameter DATA_WIDTH = 8,
38	    // Propagate tkeep signal
39	    // If disabled, tkeep assumed to be 1'b1
40	    parameter KEEP_ENABLE = (DATA_WIDTH>8),
41	    // tkeep signal width (words per cycle)
42	    parameter KEEP_WIDTH = (DATA_WIDTH/8)
43	)
44	(
45	    input  wire                  clk,
46	    input  wire                  rst,
47	
48	    /*
49	     * Ethernet frame input
50	     */
51	    input  wire                  s_eth_hdr_valid,
52	    output wire                  s_eth_hdr_ready,
53	    input  wire [47:0]           s_eth_dest_mac,
54	    input  wire [47:0]           s_eth_src_mac,
55	    input  wire [15:0]           s_eth_type,
56	    input  wire [DATA_WIDTH-1:0] s_eth_payload_axis_tdata,
57	    input  wire [KEEP_WIDTH-1:0] s_eth_payload_axis_tkeep,
58	    input  wire                  s_eth_payload_axis_tvalid,
59	    output wire                  s_eth_payload_axis_tready,
60	    input  wire                  s_eth_payload_axis_tlast,
61	    input  wire                  s_eth_payload_axis_tuser,
62	
63	    /*
64	     * AXI output
65	     */
66	    output wire [DATA_WIDTH-1:0] m_axis_tdata,
67	    output wire [KEEP_WIDTH-1:0] m_axis_tkeep,
68	    output wire                  m_axis_tvalid,
69	    input  wire                  m_axis_tready,
70	    output wire                  m_axis_tlast,
71	    output wire                  m_axis_tuser,
72	
73	    /*
74	     * Status signals
75	     */
76	    output wire                  busy
77	);
78	
79	parameter BYTE_LANES = KEEP_ENABLE ? KEEP_WIDTH : 1;
80	
81	parameter HDR_SIZE = 14;
82	
83	parameter CYCLE_COUNT = (HDR_SIZE+BYTE_LANES-1)/BYTE_LANES;
84	
85	parameter PTR_WIDTH = $clog2(CYCLE_COUNT);
86	
87	parameter OFFSET = HDR_SIZE % BYTE_LANES;
88	
89	// bus width assertions
90	initial begin
91	    if (BYTE_LANES * 8 != DATA_WIDTH) begin
92	        $error("Error: AXI stream interface requires byte (8-bit) granularity (instance %m)");
93	        $finish;
94	    end
95	end
96	
97	/*
98	
99	Ethernet frame
100	
101	 Field                       Length
102	 Destination MAC address     6 octets
103	 Source MAC address          6 octets
104	 Ethertype                   2 octets
105	
106	This module receives an Ethernet frame with header fields in parallel along
107	with the payload in an AXI stream, combines the header with the payload, and
108	transmits the complete Ethernet frame on the output AXI stream interface.
109	
110	*/
111	
112	// datapath control signals
113	reg store_eth_hdr;
114	
115	reg send_eth_header_reg = 1'b0, send_eth_header_next;
116	reg send_eth_payload_reg = 1'b0, send_eth_payload_next;
117	reg [PTR_WIDTH-1:0] ptr_reg = 0, ptr_next;
118	
119	reg flush_save;
120	reg transfer_in_save;
121	
122	reg [47:0] eth_dest_mac_reg = 48'd0;
123	reg [47:0] eth_src_mac_reg = 48'd0;
124	reg [15:0] eth_type_reg = 16'd0;
125	
126	reg s_eth_hdr_ready_reg = 1'b0, s_eth_hdr_ready_next;
127	reg s_eth_payload_axis_tready_reg = 1'b0, s_eth_payload_axis_tready_next;
128	
129	reg busy_reg = 1'b0;
130	
131	reg [DATA_WIDTH-1:0] save_eth_payload_axis_tdata_reg = {DATA_WIDTH{1'b0}};
132	reg [KEEP_WIDTH-1:0] save_eth_payload_axis_tkeep_reg = {KEEP_WIDTH{1'b0}};
133	reg save_eth_payload_axis_tlast_reg = 1'b0;
134	reg save_eth_payload_axis_tuser_reg = 1'b0;
135	
136	reg [DATA_WIDTH-1:0] shift_eth_payload_axis_tdata;
137	reg [KEEP_WIDTH-1:0] shift_eth_payload_axis_tkeep;
138	reg shift_eth_payload_axis_tvalid;
139	reg shift_eth_payload_axis_tlast;
140	reg shift_eth_payload_axis_tuser;
141	reg shift_eth_payload_axis_input_tready;
142	reg shift_eth_payload_axis_extra_cycle_reg = 1'b0;
143	
144	// internal datapath
145	reg [DATA_WIDTH-1:0] m_axis_tdata_int;
146	reg [KEEP_WIDTH-1:0] m_axis_tkeep_int;
147	reg                  m_axis_tvalid_int;
148	reg                  m_axis_tready_int_reg = 1'b0;
149	reg                  m_axis_tlast_int;
150	reg                  m_axis_tuser_int;
151	wire                 m_axis_tready_int_early;
152	
153	assign s_eth_hdr_ready = s_eth_hdr_ready_reg;
154	assign s_eth_payload_axis_tready = s_eth_payload_axis_tready_reg;
155	
156	assign busy = busy_reg;
157	
158	always @* begin
159	    if (OFFSET == 0) begin
160	        // passthrough if no overlap
161	        shift_eth_payload_axis_tdata = s_eth_payload_axis_tdata;
162	        shift_eth_payload_axis_tkeep = s_eth_payload_axis_tkeep;
163	        shift_eth_payload_axis_tvalid = s_eth_payload_axis_tvalid;
164	        shift_eth_payload_axis_tlast = s_eth_payload_axis_tlast;
165	        shift_eth_payload_axis_tuser = s_eth_payload_axis_tuser;
166	        shift_eth_payload_axis_input_tready = 1'b1;
167	    end else if (shift_eth_payload_axis_extra_cycle_reg) begin
168	        shift_eth_payload_axis_tdata = {s_eth_payload_axis_tdata, save_eth_payload_axis_tdata_reg} >> ((KEEP_WIDTH-OFFSET)*8);
169	        shift_eth_payload_axis_tkeep = {{KEEP_WIDTH{1'b0}}, save_eth_payload_axis_tkeep_reg} >> (KEEP_WIDTH-OFFSET);
170	        shift_eth_payload_axis_tvalid = 1'b1;
171	        shift_eth_payload_axis_tlast = save_eth_payload_axis_tlast_reg;
172	        shift_eth_payload_axis_tuser = save_eth_payload_axis_tuser_reg;
173	        shift_eth_payload_axis_input_tready = flush_save;
174	    end else begin
175	        shift_eth_payload_axis_tdata = {s_eth_payload_axis_tdata, save_eth_payload_axis_tdata_reg} >> ((KEEP_WIDTH-OFFSET)*8);
176	        shift_eth_payload_axis_tkeep = {s_eth_payload_axis_tkeep, save_eth_payload_axis_tkeep_reg} >> (KEEP_WIDTH-OFFSET);
177	        shift_eth_payload_axis_tvalid = s_eth_payload_axis_tvalid;
178	        shift_eth_payload_axis_tlast = (s_eth_payload_axis_tlast && ((s_eth_payload_axis_tkeep & ({KEEP_WIDTH{1'b1}} << (KEEP_WIDTH-OFFSET))) == 0));
179	        shift_eth_payload_axis_tuser = (s_eth_payload_axis_tuser && ((s_eth_payload_axis_tkeep & ({KEEP_WIDTH{1'b1}} << (KEEP_WIDTH-OFFSET))) == 0));
180	        shift_eth_payload_axis_input_tready = !(s_eth_payload_axis_tlast && s_eth_payload_axis_tready && s_eth_payload_axis_tvalid);
181	    end
182	end
183	
184	always @* begin
185	    send_eth_header_next = send_eth_header_reg;
186	    send_eth_payload_next = send_eth_payload_reg;
187	    ptr_next = ptr_reg;
188	
189	    s_eth_hdr_ready_next = 1'b0;
190	    s_eth_payload_axis_tready_next = 1'b0;
191	
192	    store_eth_hdr = 1'b0;
193	
194	    flush_save = 1'b0;
195	    transfer_in_save = 1'b0;
196	
197	    m_axis_tdata_int = {DATA_WIDTH{1'b0}};
198	    m_axis_tkeep_int = {KEEP_WIDTH{1'b0}};
199	    m_axis_tvalid_int = 1'b0;
200	    m_axis_tlast_int = 1'b0;
201	    m_axis_tuser_int = 1'b0;
202	
203	    if (s_eth_hdr_ready && s_eth_hdr_valid) begin
204	        store_eth_hdr = 1'b1;
205	        ptr_next = 0;
206	        send_eth_header_next = 1'b1;
207	        send_eth_payload_next = (OFFSET != 0) && (CYCLE_COUNT == 1);
208	        s_eth_payload_axis_tready_next = send_eth_payload_next && m_axis_tready_int_early;
209	    end
210	
211	    if (send_eth_payload_reg) begin
212	        s_eth_payload_axis_tready_next = m_axis_tready_int_early && shift_eth_payload_axis_input_tready;
213	
214	        m_axis_tdata_int = shift_eth_payload_axis_tdata;
215	        m_axis_tkeep_int = shift_eth_payload_axis_tkeep;
216	        m_axis_tlast_int = shift_eth_payload_axis_tlast;
217	        m_axis_tuser_int = shift_eth_payload_axis_tuser;
218	
219	        if ((s_eth_payload_axis_tready && s_eth_payload_axis_tvalid) || (m_axis_tready_int_reg && shift_eth_payload_axis_extra_cycle_reg)) begin
220	            transfer_in_save = 1'b1;
221	
222	            m_axis_tvalid_int = 1'b1;
223	
224	            if (shift_eth_payload_axis_tlast) begin
225	                flush_save = 1'b1;
226	                s_eth_payload_axis_tready_next = 1'b0;
227	                ptr_next = 0;
228	                send_eth_payload_next = 1'b0;
229	            end
230	        end
231	    end
232	
233	    if (m_axis_tready_int_reg && (!OFFSET || !send_eth_payload_reg || m_axis_tvalid_int)) begin
234	        if (send_eth_header_reg) begin
235	            ptr_next = ptr_reg + 1;
236	
237	            if ((OFFSET != 0) && (CYCLE_COUNT == 1 || ptr_next == CYCLE_COUNT-1) && !send_eth_payload_reg) begin
238	                send_eth_payload_next = 1'b1;
239	                s_eth_payload_axis_tready_next = m_axis_tready_int_early && shift_eth_payload_axis_input_tready;
240	            end
241	
242	            m_axis_tvalid_int = 1'b1;
243	
244	            `define _HEADER_FIELD_(offset, field) \
245	                if (ptr_reg == offset/BYTE_LANES) begin \
246	                    m_axis_tdata_int[(offset%BYTE_LANES)*8 +: 8] = field; \
247	                    m_axis_tkeep_int[offset%BYTE_LANES] = 1'b1; \
248	                end
249	
250	            `_HEADER_FIELD_(0,  eth_dest_mac_reg[5*8 +: 8])
251	            `_HEADER_FIELD_(1,  eth_dest_mac_reg[4*8 +: 8])
252	            `_HEADER_FIELD_(2,  eth_dest_mac_reg[3*8 +: 8])
253	            `_HEADER_FIELD_(3,  eth_dest_mac_reg[2*8 +: 8])
254	            `_HEADER_FIELD_(4,  eth_dest_mac_reg[1*8 +: 8])
255	            `_HEADER_FIELD_(5,  eth_dest_mac_reg[0*8 +: 8])
256	            `_HEADER_FIELD_(6,  eth_src_mac_reg[5*8 +: 8])
257	            `_HEADER_FIELD_(7,  eth_src_mac_reg[4*8 +: 8])
258	            `_HEADER_FIELD_(8,  eth_src_mac_reg[3*8 +: 8])
259	            `_HEADER_FIELD_(9,  eth_src_mac_reg[2*8 +: 8])
260	            `_HEADER_FIELD_(10, eth_src_mac_reg[1*8 +: 8])
261	            `_HEADER_FIELD_(11, eth_src_mac_reg[0*8 +: 8])
262	            `_HEADER_FIELD_(12, eth_type_reg[1*8 +: 8])
263	            `_HEADER_FIELD_(13, eth_type_reg[0*8 +: 8])
264	
265	            if (ptr_reg == 13/BYTE_LANES) begin
266	                if (!send_eth_payload_reg) begin
267	                    s_eth_payload_axis_tready_next = m_axis_tready_int_early;
268	                    send_eth_payload_next = 1'b1;
269	                end
270	                send_eth_header_next = 1'b0;
271	            end
272	
273	            `undef _HEADER_FIELD_
274	        end
275	    end
276	
277	    s_eth_hdr_ready_next = !(send_eth_header_next || send_eth_payload_next);
278	end
279	
280	always @(posedge clk) begin
281	    send_eth_header_reg <= send_eth_header_next;
282	    send_eth_payload_reg <= send_eth_payload_next;
283	    ptr_reg <= ptr_next;
284	
285	    s_eth_hdr_ready_reg <= s_eth_hdr_ready_next;
286	    s_eth_payload_axis_tready_reg <= s_eth_payload_axis_tready_next;
287	
288	    busy_reg <= send_eth_header_next || send_eth_payload_next;
289	
290	    if (store_eth_hdr) begin
291	        eth_dest_mac_reg <= s_eth_dest_mac;
292	        eth_src_mac_reg <= s_eth_src_mac;
293	        eth_type_reg <= s_eth_type;
294	    end
295	
296	    if (transfer_in_save) begin
297	        save_eth_payload_axis_tdata_reg <= s_eth_payload_axis_tdata;
298	        save_eth_payload_axis_tkeep_reg <= s_eth_payload_axis_tkeep;
299	        save_eth_payload_axis_tuser_reg <= s_eth_payload_axis_tuser;
300	    end
301	
302	    if (flush_save) begin
303	        save_eth_payload_axis_tlast_reg <= 1'b0;
304	        shift_eth_payload_axis_extra_cycle_reg <= 1'b0;
305	    end else if (transfer_in_save) begin
306	        save_eth_payload_axis_tlast_reg <= s_eth_payload_axis_tlast;
307	        shift_eth_payload_axis_extra_cycle_reg <= OFFSET ? s_eth_payload_axis_tlast && ((s_eth_payload_axis_tkeep & ({KEEP_WIDTH{1'b1}} << (KEEP_WIDTH-OFFSET))) != 0) : 1'b0;
308	    end
309	
310	    if (rst) begin
311	        send_eth_header_reg <= 1'b0;
312	        send_eth_payload_reg <= 1'b0;
313	        ptr_reg <= 0;
314	        s_eth_hdr_ready_reg <= 1'b0;
315	        s_eth_payload_axis_tready_reg <= 1'b0;
316	        busy_reg <= 1'b0;
317	    end
318	end
319	
320	// output datapath logic
321	reg [DATA_WIDTH-1:0] m_axis_tdata_reg = {DATA_WIDTH{1'b0}};
322	reg [KEEP_WIDTH-1:0] m_axis_tkeep_reg = {KEEP_WIDTH{1'b0}};
323	reg                  m_axis_tvalid_reg = 1'b0, m_axis_tvalid_next;
324	reg                  m_axis_tlast_reg = 1'b0;
325	reg                  m_axis_tuser_reg = 1'b0;
326	
327	reg [DATA_WIDTH-1:0] temp_m_axis_tdata_reg = {DATA_WIDTH{1'b0}};
328	reg [KEEP_WIDTH-1:0] temp_m_axis_tkeep_reg = {KEEP_WIDTH{1'b0}};
329	reg                  temp_m_axis_tvalid_reg = 1'b0, temp_m_axis_tvalid_next;
330	reg                  temp_m_axis_tlast_reg = 1'b0;
331	reg                  temp_m_axis_tuser_reg = 1'b0;
332	
333	// datapath control
334	reg store_axis_int_to_output;
335	reg store_axis_int_to_temp;
336	reg store_axis_temp_to_output;
337	
338	assign m_axis_tdata = m_axis_tdata_reg;
339	assign m_axis_tkeep = KEEP_ENABLE ? m_axis_tkeep_reg : {KEEP_WIDTH{1'b1}};
340	assign m_axis_tvalid = m_axis_tvalid_reg;
341	assign m_axis_tlast = m_axis_tlast_reg;
342	assign m_axis_tuser = m_axis_tuser_reg;
343	
344	// enable ready input next cycle if output is ready or if both output registers are empty
345	assign m_axis_tready_int_early = m_axis_tready || (!temp_m_axis_tvalid_reg && !m_axis_tvalid_reg);
346	
347	always @* begin
348	    // transfer sink ready state to source
349	    m_axis_tvalid_next = m_axis_tvalid_reg;
350	    temp_m_axis_tvalid_next = temp_m_axis_tvalid_reg;
351	
352	    store_axis_int_to_output = 1'b0;
353	    store_axis_int_to_temp = 1'b0;
354	    store_axis_temp_to_output = 1'b0;
355	    
356	    if (m_axis_tready_int_reg) begin
357	        // input is ready
358	        if (m_axis_tready || !m_axis_tvalid_reg) begin
359	            // output is ready or currently not valid, transfer data to output
360	            m_axis_tvalid_next = m_axis_tvalid_int;
361	            store_axis_int_to_output = 1'b1;
362	        end else begin
363	            // output is not ready, store input in temp
364	            temp_m_axis_tvalid_next = m_axis_tvalid_int;
365	            store_axis_int_to_temp = 1'b1;
366	        end
367	    end else if (m_axis_tready) begin
368	        // input is not ready, but output is ready
369	        m_axis_tvalid_next = temp_m_axis_tvalid_reg;
370	        temp_m_axis_tvalid_next = 1'b0;
371	        store_axis_temp_to_output = 1'b1;
372	    end
373	end
374	
375	always @(posedge clk) begin
376	    m_axis_tvalid_reg <= m_axis_tvalid_next;
377	    m_axis_tready_int_reg <= m_axis_tready_int_early;
378	    temp_m_axis_tvalid_reg <= temp_m_axis_tvalid_next;
379	
380	    // datapath
381	    if (store_axis_int_to_output) begin
382	        m_axis_tdata_reg <= m_axis_tdata_int;
383	        m_axis_tkeep_reg <= m_axis_tkeep_int;
384	        m_axis_tlast_reg <= m_axis_tlast_int;
385	        m_axis_tuser_reg <= m_axis_tuser_int;
386	    end else if (store_axis_temp_to_output) begin
387	        m_axis_tdata_reg <= temp_m_axis_tdata_reg;
388	        m_axis_tkeep_reg <= temp_m_axis_tkeep_reg;
389	        m_axis_tlast_reg <= temp_m_axis_tlast_reg;
390	        m_axis_tuser_reg <= temp_m_axis_tuser_reg;
391	    end
392	
393	    if (store_axis_int_to_temp) begin
394	        temp_m_axis_tdata_reg <= m_axis_tdata_int;
395	        temp_m_axis_tkeep_reg <= m_axis_tkeep_int;
396	        temp_m_axis_tlast_reg <= m_axis_tlast_int;
397	        temp_m_axis_tuser_reg <= m_axis_tuser_int;
398	    end
399	
400	    if (rst) begin
401	        m_axis_tvalid_reg <= 1'b0;
402	        m_axis_tready_int_reg <= 1'b0;
403	        temp_m_axis_tvalid_reg <= 1'b0;
404	    end
405	end
406	
407	endmodule
408	
409	`resetall
410

